CREATE TABLE "authorized_signature_versions" ("id" UUID NOT NULL,"companyId" UUID NOT NULL,"objectKey" VARCHAR(500) NOT NULL,"uploadedById" UUID NOT NULL,"isCurrent" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"retiredAt" TIMESTAMP(3),CONSTRAINT "authorized_signature_versions_pkey" PRIMARY KEY ("id"),CONSTRAINT "authorized_signature_versions_company_fkey" FOREIGN KEY ("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT ON UPDATE RESTRICT,CONSTRAINT "authorized_signature_versions_uploader_fkey" FOREIGN KEY ("companyId","uploadedById") REFERENCES "users"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE UNIQUE INDEX "authorized_signature_versions_companyId_objectKey_key" ON "authorized_signature_versions"("companyId","objectKey");
CREATE INDEX "authorized_signature_versions_companyId_isCurrent_createdAt_idx" ON "authorized_signature_versions"("companyId","isCurrent","createdAt");
ALTER TABLE "commercial_documents" ADD COLUMN "signatureVersionId" UUID;
ALTER TABLE "commercial_documents" ADD CONSTRAINT "commercial_documents_signatureVersionId_fkey" FOREIGN KEY ("signatureVersionId") REFERENCES "authorized_signature_versions"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
